$insert = "  // 2-Step plan — show its own full detail page`n  if (activePlan === `"2step`") {`n    const twoStepUrl = `"https://fundedwealth.com/rules?plan=2step`";`n    const handleTwoStepShare = async () => {`n      if (navigator.share) {`n        try { await navigator.share({ title: `"FundedWealth 2-Step Rules`", text: `"Check out the 2-Step challenge rules on FundedWealth.`", url: twoStepUrl }); } catch (_) {}`n      } else {`n        await navigator.clipboard.writeText(twoStepUrl);`n        setTwoStepLinkCopied(true);`n        setTimeout(() => setTwoStepLinkCopied(false), 2000);`n      }`n    };`n    return (`n      <div className=`"min-h-screen bg-[#0D0020] text-white`">`n        <div className=`"sticky top-0 z-40 bg-[#1A0030]/95 backdrop-blur-md border-b border-white/10 py-4`">`n          <div className=`"container mx-auto px-4 flex items-center justify-between`">`n            <button onClick={() => setActivePlan(null)} className=`"flex items-center gap-2 text-white/70 hover:text-white transition-colors`">`n              <ArrowLeft size={20} />`n              <img src=`"/logo.png`" alt=`"FundedWealth`" className=`"h-8 w-8 rounded-lg`" />`n              <span className=`"font-heading font-bold hidden sm:block`">FundedWealth</span>`n            </button>`n            <h1 className=`"text-lg font-heading font-bold flex items-center gap-2`">`n              <Layers className=`"text-purple-400`" size={18} /> 2-Step Rules`n            </h1>`n            <div className=`"flex items-center gap-2`">`n              <button onClick={handleTwoStepShare}`n                className={`${`"``"}`flex items-center gap-1.5 px-3 py-1.5 rounded-lg border text-xs font-bold transition-all duration-200 `${twoStepLinkCopied ? `"bg-green-500/15 border-green-500/40 text-green-300`" : `"bg-white/[0.05] border-white/15 text-white/70 hover:text-white hover:bg-white/10 hover:border-white/30`"}`${`"``"}}`n                title=`"Share 2-Step Rules link`">`n                {twoStepLinkCopied ? <><Check size={13} /> Copied!</> : <><Share2 size={13} /> Share</>}`n              </button>`n              <Link href=`"/`"><Button variant=`"ghost`" className=`"text-white/70 hover:text-white`">Home</Button></Link>`n            </div>`n          </div>`n        </div>`n        <div className=`"container mx-auto px-4 py-12`">`n          <TwoStepRulesDetail onBack={() => setActivePlan(null)} />`n        </div>`n      </div>`n    );`n  }`n`n"

